110	          <input value={telefone} onChange={(e) => setTelefone(e.target.value)} placeholder="Telefone do cliente" required
111	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
112	          {erro && <p className="text-xs text-red-600">{erro}</p>}
113	          <div className="flex gap-2 pt-1">
114	            <button type="button" onClick={onFechar}
115	              className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
116	              Cancelar
117	            </button>
118	            <button type="submit" disabled={salvando}
119	              className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
120	              {salvando ? 'Abrindo...' : 'Abrir'}
121	            </button>
122	          </div>
123	        </form>
124	      </div>
125	    </div>
126	  );
