348	const PagamentoParcial = ({ comanda, onRegistrado, podePagamentoParcial }) => {
349	  const [valor, setValor] = useState('');
350	  const [forma, setForma] = useState('pix');
351	  const [valorRecebido, setValorRecebido] = useState('');
352	  const [erro, setErro] = useState(null);
353	  const [salvando, setSalvando] = useState(false);
354	  const [editandoId, setEditandoId] = useState(null);
355	  const [valorEdicao, setValorEdicao] = useState('');
356	  const [formaEdicao, setFormaEdicao] = useState('pix');
357	
358	  const saldo = comanda.saldo?.saldo ?? 0;
359	  const troco = forma === 'cash' && valorRecebido ? Number(valorRecebido) - Number(valor || 0) : null;
360	  // Comanda paga/cancelada não deixa mais mexer nos pagamentos, mesma regra de editar itens.
361	  const podeMexer = ['aberta', 'fechada_garcom'].includes(comanda.status);
362	
363	  const registrar = async () => {
364	    const v = Number(valor);
365	    if (!v || v <= 0) return;
366	    if (forma === 'cash' && valorRecebido && Number(valorRecebido) < v) {
367	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
368	      return;
369	    }
370	    setErro(null);
371	    setSalvando(true);
372	    try {
373	      await registrarPagamento(comanda.id, v, forma, forma === 'cash' && valorRecebido ? Number(valorRecebido) : undefined);
374	      setValor('');
375	      setValorRecebido('');
376	      await onRegistrado();
377	    } catch (err) {
378	      setErro(err.message ?? 'Não foi possível registrar o pagamento.');
379	    } finally {
380	      setSalvando(false);
381	    }
382	  };
383	
384	  const iniciarEdicao = (p) => {
385	    setEditandoId(p.id);
386	    setValorEdicao(String(p.valor));
387	    setFormaEdicao(p.forma_pagamento);
388	  };
389	
390	  const salvarEdicao = async () => {
391	    const v = Number(valorEdicao);
392	    if (!v || v <= 0) return;
393	    setErro(null);
394	    setSalvando(true);
395	    try {
396	      await editarPagamento(comanda.id, editandoId, v, formaEdicao);
397	      setEditandoId(null);
398	      await onRegistrado();
399	    } catch (err) {
400	      setErro(err.message ?? 'Não foi possível editar o pagamento.');
401	    } finally {
402	      setSalvando(false);
403	    }
404	  };
405	
406	  const remover = async (p) => {
407	    if (!window.confirm('Remover este pagamento?')) return;
408	    setErro(null);
409	    try {
410	      await removerPagamento(comanda.id, p.id);
411	      await onRegistrado();
412	    } catch (err) {
413	      setErro(err.message ?? 'Não foi possível remover o pagamento.');
414	    }
415	  };
416	
417	  return (
418	    <div className="bg-white rounded-xl border border-[#E4E4E7] p-3 space-y-2">
419	      <div className="flex justify-between text-sm">
420	        <span className="text-[#71717A]">Saldo devedor</span>
421	        <strong className={saldo > 0.01 ? 'text-[#FF441F]' : 'text-emerald-600'}>{fmt(saldo)}</strong>
422	      </div>
423	      {(comanda.pagamentos ?? []).length > 0 && (
424	        <div className="space-y-1">
425	          {comanda.pagamentos.map((p) => (
426	            editandoId === p.id ? (
427	              <div key={p.id} className="flex items-center gap-1.5 bg-[#F4F4F5] rounded-lg p-1.5">
