12	  me(@Req() req: any) {
13	    return {
14	      id: req.garcomId,
15	      nome: req.garcomNome,
16	      restauranteAberto: req.restauranteAberto,
17	      permissoes: req.garcomPermissoes,
18	      salaoModo: req.salaoModo,
19	    };
20	  }
21	
22	  @Get('mesas')
23	  mesas(@Req() req: any) {
24	    return this.service.mesas(req.garcomRestaurantId);
25	  }
26	
27	  @Get('produtos')
28	  produtos(@Req() req: any) {
29	    return this.service.produtos(req.garcomRestaurantId);
30	  }
31	
32	  @Get('comandas')
33	  minhasComandas(@Req() req: any) {
34	    return this.service.minhasComandas(req.garcomId);
35	  }
36	
37	  @Get('itens-prontos')
38	  itensProntos(@Req() req: any) {
39	    return this.service.itensProntos(req.garcomId);
40	  }
41	
42	  @Get('comandas/:id')
43	  obterComanda(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
44	    return this.service.obterComanda(id, req.garcomId);
45	  }
