774	  // (cozinha, bar, salgados...) — lista PLANA de itens (não agrupa por mesa/comanda,
775	  // cada item tem sua própria ação de preparo/impressão), ordenada por chegada.
776	  async getKdsSetor(restaurantId: number, impressoraId: number) {
777	    // Itens "pronto" recentes (últimos 10min) também entram — sem isso, um clique errado
778	    // em "Entregue"/"Pronto" faz o item sumir da tela sem chance de desfazer.
779	    const limiteProntos = new Date(Date.now() - 10 * 60 * 1000).toISOString();
780	    const { data: itens, error } = await this.supabase.client
781	      .from('order_items')
782	      .select('id, quantity, unit_price, observacao, product_id, status, enviado_em, preparando_em, pronto_em, order_id, products(name), orders(id, restaurant_id, mesa_id, cliente_mesa_nome, garcom_id, customer_id, status, motoboy_lat, motoboy_lng, delivery_occurrence, mesas(numero, nome), garcons(nome))')
783	      .eq('impressora_id', impressoraId)
784	      .or(`status.in.(enviado,preparando),and(status.eq.pronto,pronto_em.gte.${limiteProntos})`)
785	      .order('enviado_em', { ascending: true });
786	    if (error) throw error;
787	
788	    const itensValidos = (itens as any[]).filter((i) => i.orders?.restaurant_id === restaurantId);
789	
790	    // Um item roteado pra uma impressora/setor pode vir tanto de comanda do salão
791	    // (mesa_id/garcom_id preenchidos) quanto de pedido de delivery (produto com a
792	    // mesma impressora configurada) — resolve nome do cliente de delivery à parte
793	    // pra tela poder filtrar e exibir por canal.
794	    const customerIds = [...new Set(itensValidos.map((i) => i.orders?.customer_id).filter(Boolean))];
795	    const { data: customers } = customerIds.length
796	      ? await this.supabase.client.from('customers').select('id, name').in('id', customerIds)
797	      : { data: [] as any[] };
798	    const customerMap = Object.fromEntries((customers ?? []).map((c: any) => [c.id, c.name]));
799	
800	    return {
801	      itens: itensValidos.map((i) => {
802	        const ehSalao = !!(i.orders?.mesa_id || i.orders?.garcom_id || i.orders?.cliente_mesa_nome);
803	        return {
804	          id: i.id,
805	          order_id: i.order_id,
806	          product_name: i.products?.name,
807	          quantity: i.quantity,
808	          observacao: i.observacao,
809	          status: i.status,
810	          enviado_em: i.enviado_em,
811	          preparando_em: i.preparando_em,
812	          pronto_em: i.pronto_em,
813	          tipo: ehSalao ? 'salao' : 'delivery',
814	          mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
815	          cliente: i.orders?.cliente_mesa_nome ?? (i.orders?.customer_id ? customerMap[i.orders.customer_id] ?? null : null),
816	          garcom: i.orders?.garcons?.nome ?? null,
817	          // Status de entrega do pedido (delivery) — usado no Bar pra alerta de motoboy
818	          // (em trânsito/entregue/ocorrência) e botão de localizar no mapa.
819	          pedido_status: i.orders?.status ?? null,
820	          motoboy_lat: i.orders?.motoboy_lat ?? null,
821	          motoboy_lng: i.orders?.motoboy_lng ?? null,
822	          delivery_occurrence: i.orders?.delivery_occurrence ?? null,
823	        };
824	      }),
825	    };
826	  }
