828	  // Move só esse item de "aguardando" (enviado) pra "preparando" — ação por item, não
829	  // por comanda inteira (cada prato tem seu próprio ritmo de preparo).
830	  async iniciarPreparoItem(itemId: number, restaurantId: number) {
831	    const { data: item } = await this.supabase.client
832	      .from('order_items')
833	      .select('id, order_id, orders(restaurant_id)')
834	      .eq('id', itemId)
835	      .maybeSingle();
836	    if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
837	      throw new NotFoundException('Item não encontrado');
838	    }
839	
840	    const { error } = await this.supabase.client
841	      .from('order_items')
842	      .update({ status: 'preparando', preparando_em: new Date().toISOString() })
843	      .eq('id', itemId);
844	    if (error) throw error;
845	
846	    return { ok: true };
847	  }
