312	  async cancelarCliente(id: number, userId: string, motivo: string) {
313	    if (!motivo?.trim()) throw new BadRequestException('Motivo do cancelamento é obrigatório');
314	
315	    const { data: pedido, error } = await this.supabase.client
316	      .from('orders')
317	      .select('id, status, user_id, total, payment_method')
318	      .eq('id', id)
319	      .maybeSingle();
320	
321	    if (error) throw error;
322	    if (!pedido) throw new NotFoundException(`Pedido ${id} não encontrado`);
323	    if (pedido.user_id !== userId) throw new ForbiddenException('Sem permissão para cancelar este pedido');
324	    if (!['pending', 'confirmed'].includes(pedido.status)) {
325	      throw new BadRequestException('Pedido não pode ser cancelado após início do preparo');
326	    }
327	
328	    const { data: pagamento } = await this.supabase.client
329	      .from('pagamentos')
330	      .select('id, valor, tipo')
331	      .eq('order_id', id)
332	      .eq('status', 'paid')
333	      .maybeSingle();
334	
335	    const { data: atualizado, error: errUpd } = await this.supabase.client
336	      .from('orders')
337	      .update({ status: 'canceled', cancel_reason: motivo.trim(), updated_at: new Date().toISOString() })
338	      .eq('id', id)
339	      .select('id, status, cancel_reason, total, updated_at')
340	      .single();
341	
342	    if (errUpd) throw errUpd;
343	
344	    const valor_devolver = pagamento?.valor ?? 0;
345	    return {
346	      pedido: atualizado,
347	      valor_devolver,
348	      precisa_estorno: valor_devolver > 0,
349	    };
350	  }
351	}
